import csv

def average_by_city(path):
    scores = {}
    with open(path, newline='', encoding='utf-8') as f:
        for row in csv.DictReader(f):
            scores.setdefault(row['city'], []).append(int(row['score']))
    return {city: round(sum(v) / len(v), 1) for city, v in scores.items()}
